/** `flow.shape` — its nodes, its `start` edges, and the compiled graph. */
function flowShape() {
  return new StateGraph(State)
    .addNode("shape", (state: GraphState) => runtime.runNode(flowShapeNodeShape, state), {
      ends: ["ask"],
    })
    .addNode("ask", (state: GraphState) => runtime.runNode(flowShapeNodeAsk, state), {
      ends: ["probe"],
    })
    .addNode("probe", (state: GraphState) => runtime.runNode(flowShapeNodeProbe, state), {
      ends: ["notify"],
    })
    .addNode("notify", (state: GraphState) => runtime.runNode(flowShapeNodeNotify, state), {
      ends: ["recall"],
    })
    .addNode("recall", (state: GraphState) => runtime.runNode(flowShapeNodeRecall, state), {
      ends: ["spread"],
    })
    .addNode("spread", (state: GraphState) => runtime.runNode(flowShapeNodeSpread, state), {
      ends: ["claim"],
    })
    .addNode("claim", (state: GraphState) => runtime.runNode(flowShapeNodeClaim, state), {
      ends: ["stamp"],
    })
    .addNode("stamp", (state: GraphState) => runtime.runNode(flowShapeNodeStamp, state), {
      ends: ["tick"],
    })
    .addNode("tick", (state: GraphState) => runtime.runNode(flowShapeNodeTick, state), {
      ends: ["tidy"],
    })
    .addNode("tidy", (state: GraphState) => runtime.runNode(flowShapeNodeTidy, state), {
      ends: ["drop"],
    })
    .addNode("drop", (state: GraphState) => runtime.runNode(flowShapeNodeDrop, state), {
      ends: ["page"],
    })
    .addNode("page", (state: GraphState) => runtime.runNode(flowShapeNodePage, state), {
      ends: ["tally"],
    })
    .addNode("tally", (state: GraphState) => runtime.runNode(flowShapeNodeTally, state), {
      ends: ["fetch"],
    })
    .addNode("fetch", (state: GraphState) => runtime.runNode(flowShapeNodeFetch, state), {
      ends: ["shift"],
    })
    .addNode("shift", (state: GraphState) => runtime.runNode(flowShapeNodeShift, state), {
      ends: ["record"],
    })
    .addNode("record", (state: GraphState) => runtime.runNode(flowShapeNodeRecord, state), {
      ends: ["close"],
    })
    .addNode("close", (state: GraphState) => runtime.runNode(flowShapeNodeClose, state), {
      ends: [END],
    })
    .addEdge(START, "shape")
    .compile();
}

/**
 * `flow.shape`, compiled once. Building it at import is also what checks it: a state model LangGraph refuses, or an edge to a node that is not registered, fails here rather than at the first invocation.
 */
const flowShapeGraph = flowShape();

/**
 * `flow.shape` as a module: what a `flow:` node instantiates and a `map` dispatches to (grammar 7.5, 8.5).
 */
const flowShapeBinding: runtime.SubflowBinding = {
  address: "flow.shape",
  outputs: ["draft", "notes"],
  recursionLimit: 42,
  stream: (initial, options) =>
    flowShapeGraph.stream(initial, {
      ...options,
      streamMode: "values",
      outputKeys: flowShapeGraph.outputChannels,
    }) as unknown as Promise<AsyncIterable<runtime.GraphStateLike>>,
};

/**
 * How a declared flow input reads a command-line value (grammar 13.2).
 *
 * `json` is every structured shape — an object, an array, a tagged union — for
 * which the one honest reading of a shell argument is the document it spells.
 */
export type InputKind = "string" | "integer" | "number" | "boolean" | "json";

/** One compiled flow: what it takes, what it answers, and how to run it. */
export interface CompiledFlow {
  /** Its typed address (grammar 2.2). */
  readonly address: string;
  /** The fields its `inputs:` declares (grammar 7.5). */
  readonly inputs: readonly string[];
  /**
   * What each declared input *is*, so a `--input k=v` argument can be read as
   * the type the field declares rather than reaching Zod as text (grammar 13.2).
   */
  readonly inputKinds: Readonly<Record<string, InputKind>>;
  /** The fields its `outputs:` declares, each read from the channel of that name. */
  readonly outputs: readonly string[];
  /**
   * The `scope: session` stores this flow **reaches**, under the relation
   * grammar 7.7 fixes — its own nodes, its maps' dispatch targets, the flows it
   * instantiates, and the stores of every agent it reaches.
   *
   * A run of this flow needs a session identity exactly when this list is not
   * empty (grammar 11.3): a declared trigger supplies it through `session_key:`,
   * and the CLI through `--session`. Checked at run start rather than at
   * validate, for the reason env-ref presence is: the value does not exist until
   * the invocation does.
   */
  readonly sessionStores: readonly string[];
  /** The superstep ceiling a run of it takes by default. */
  readonly recursionLimit: number;
  /**
   * The node its `finally:` names, where it declares one: run once when a run
   * of it ends — completed, failed, or cancelled — beside the graph rather than
   * in it, since no edge reaches it (grammar 7.9, `runtime.endInstance`).
   */
  readonly finally?: runtime.NodeDescriptor;
  /** Parse an invocation's inputs against the flow's own schema (grammar 13.2). */
  parse(inputs: unknown): Record<string, unknown>;
  /**
   * Invoke the compiled graph, answering with the state after each superstep.
   *
   * A stream rather than a plain invocation because of what a **failure** must
   * leave behind. LangGraph's `invoke` is this stream with the last value kept,
   * and an error thrown out of it discards the state it was keeping — the
   * routing trace of PRD 5.3 with it, since nothing here is checkpointed. Taking
   * the supersteps one at a time keeps every one that did complete, which is
   * what `runFlow` reports the failure with.
   */
  stream(
    initial: Record<string, unknown>,
    options: { recursionLimit: number },
  ): Promise<AsyncIterable<GraphState>>;
}

/**
 * Every flow this composition declares, by address.
 *
 * PRD 5.11 makes manual invocation universal — every flow is runnable whether or
 * not a `manual` trigger names it (Decision D64) — so the registry is every
 * flow rather than every triggered one.
 */
export const flows: Readonly<Record<string, CompiledFlow>> = {
  "flow.condense": {
    address: "flow.condense",
    inputs: ["passage"],
    inputKinds: { "passage": "string", },
    outputs: ["latest"],
    sessionStores: [],
    recursionLimit: 27,
    finally: flowCondenseNodeNote,
    parse: (inputs: unknown) =>
      runtime.parseResult(flowCondenseInputs, inputs, "the `inputs:` of `flow.condense`") as Record<string, unknown>,
    stream: (initial, options) =>
      flowCondenseGraph.stream(initial, {
        ...options,
        streamMode: "values",
        outputKeys: flowCondenseGraph.outputChannels,
      }) as unknown as Promise<AsyncIterable<GraphState>>,
  },
  "flow.shape": {
    address: "flow.shape",
    inputs: ["goal", "goals"],
    inputKinds: { "goal": "string", "goals": "json", },
    outputs: ["draft", "notes"],
    sessionStores: [],
    recursionLimit: 42,
    parse: (inputs: unknown) =>
      runtime.parseResult(flowShapeInputs, inputs, "the `inputs:` of `flow.shape`") as Record<string, unknown>,
    stream: (initial, options) =>
      flowShapeGraph.stream(initial, {
        ...options,
        streamMode: "values",
        outputKeys: flowShapeGraph.outputChannels,
      }) as unknown as Promise<AsyncIterable<GraphState>>,
  },
};

/** What one run produced. */
export interface FlowRun {
  /** The flow's `outputs:`, materialized from state at quiescence (grammar 7.6.3). */
  readonly outputs: Record<string, unknown>;
  /**
   * Every routing decision the run made, in step order (PRD 5.3) — and last, the
   * entry of the flow's `finally:` node where it declares one (grammar 7.9).
   */
  readonly trace: readonly runtime.TraceEntry[];
  /**
   * The whole state at quiescence, with the `finally:` node's writes applied
   * after the outputs above were read from it.
   */
  readonly state: GraphState;
  /**
   * What a `finally:` node of this execution raised after its own retries,
   * where one did (grammar 7.9, PRD resolved q76): `finally_error` on the
   * execution's record. A run that carries one still completed — its outputs
   * are what its body produced.
   */
  readonly finallyError?: string;
}

/**
 * Why a flow that reaches a `scope: session` store refuses a run that arrived
 * with no session identity (grammar 11.3, 13.2).
 *
 * One sentence in one place, because it is raised from two and the two must not
 * drift: `src/cli.ts` raises it as a **usage** error, before a `run` starts
 * anything, because a missing `--session` is an argument the caller has to add —
 * the same class as an unknown `--input` name or an absent `${ENV}`, which
 * grammar 11.3 says outright by likening this check to env-ref presence (§4.3);
 * `runFlow` raises it for every other caller, where the key arrives per
 * invocation.
 *
 * Named by the store rather than by the flow, because the store is what the
 * author has to look at. And three ways a run arrives with none are named,
 * because two of them are advice a reader has already taken: a declared
 * `session_key:` that *evaluated* to the empty string — an absent header, a
 * payload member that was not sent — is an identity-less run whose trigger does
 * declare one, and a message offering only the two remedies would send that
 * reader to look at a line that is already there (PRD G3).
 */
export function sessionRefusal(address: string, stores: readonly string[]): string {
  return `\`${address}\` reaches ${stores.map((store) => `\`${store}\``).join(", ")}, which ${stores.length === 1 ? "is" : "are"} \`scope: session\`, so this run needs a session identity and arrived with none: pass \`--session <key>\` to \`agent-compose run\`, or declare \`session_key:\` on the trigger that starts it — and where one is declared, it answered the empty string for this invocation (grammar 11.3, 13.2)`;
}

/**
 * Run one flow to quiescence and materialize its outputs.
 *
 * This is the invocation surface `agent-compose run` and the generated `serve`
 * app are built on (PRD 5.11's `start`), and what an ejected project calls
 * directly. The inputs are parsed against the flow's own `inputs:` schema before
 * anything runs, which is where an invocation that the flow cannot accept is
 * refused by field name (grammar 13.2) — every invocation's but a **child
 * execution's**, which runs on what its dispatch bound, as any dispatched
 * instance does, and opens its row before anything can refuse it (see the note
 * at the top of the body).
 *
 * A run that produces no answer raises `runtime.FlowFailure`, which carries the
 * trace it did make and the original error as its `cause` — see
 * `CompiledFlow.stream` for why the run is streamed to keep it. Both of the ways
 * that happens raise it: a run that never reached quiescence, and a run that
 * reached quiescence holding no value for one of its `outputs:` fields
 * (grammar 10.1, Decision D78). The second is the one whose trace is complete —
 * every step landed — so dropping it there would lose the whole routing record
 * of a run that made one.
 *
 * A third way is a `human` node (grammar 8.7): a run that reaches one and was
 * started with **no answer surface** stops there, and the `FlowFailure` carries
 * a `runtime.HumanInterrupt` on its `cause` chain — `runtime.interruptOf` is how
 * a caller tells that outcome from a failure. `resumable: true` is what says an
 * answer surface is attached, and there are two callers that pass it, one per
 * surface (PRD §9.21): `src/serve.ts`, whose `POST /executions/:id/resume`
 * delivers the answer, and `src/cli.ts`, when the `run` it is serving may ask
 * at the terminal it was launched from.
 *
 * # Every invocation is journaled
 *
 * PRD resolved q26–q29: the run's effects are written to this project's journal
 * as they happen, and `resume: true` re-runs the graph consuming that record
 * read-only up to the frontier. Journaling is unconditional — every target this
 * compiler builds is process-local and binds the SQLite journal beside the
 * project (resolved q27) — so a caller that says nothing about durability still
 * gets it. `docs/durability.md` is normative.
 */
export async function runFlow(
  address: string,
  inputs: unknown = {},
  options: {
    readonly executionId?: string;
    readonly sessionKey?: string;
    readonly recursionLimit?: number;
    /**
     * Whether something is standing by to answer a `human` pause this run
     * reaches (grammar 8.7, PRD 5.11).
     *
     * `false` — the default, and what an `agent-compose run` with nobody to ask
     * leaves it at — makes a pause the end of the run rather than a wait
     * nothing can settle. `src/cli.ts` passes `true` where the run may ask at
     * its own standard input, and `src/serve.ts` passes it for the resume
     * route.
     */
    readonly resumable?: boolean;
    /**
     * What started this execution, for the journal's lifecycle row.
     *
     * `manual` where nothing says otherwise, which is every `agent-compose run`
     * and every `manual` trigger; `src/serve.ts` passes the `http` trigger's own
     * name. Recorded and never dispatched on — recovery replays executions, it
     * does not re-fire triggers (PRD resolved q28).
     */
    readonly trigger?: string;
    /**
     * The completion webhook of an `async` `http` trigger, resolved against the
     * request that started this execution (grammar 13.3).
     *
     * `src/serve.ts` passes it and nothing else does. It goes on the journal's
     * lifecycle row because the process that finishes an execution need not be
     * the one that started it: a `serve` that restarts mid-run recovers the
     * execution and has to be able to call the caller back
     * (`docs/durability.md` §6.1).
     */
    readonly callback?: string;
    /**
     * The W3C `traceparent` the request that started this execution carried,
     * where it carried a valid one (PRD resolved q51).
     *
     * `src/serve.ts` passes it and nothing else does, for `callback`'s reason:
     * the trace this deployment exports at settle adopts its caller's trace, and
     * the process that settles an execution need not be the one that read the
     * header (`docs/trace.md` §12.3).
     */
    readonly traceparent?: string;
    /**
     * Whether this is a **resumed** generation of an execution the journal
     * already holds (PRD resolved q29).
     *
     * `true` makes every effect site consult the journal before it calls the
     * world: a recorded answer is returned byte for byte and nothing is
     * re-issued, until the frontier — the first effect the journal does not
     * hold — where the execution goes live again. `executionId` names which
     * execution, and `inputs`/`sessionKey` must be the ones the journal
     * recorded, which is why the two callers that resume read them back off the
     * lifecycle row rather than composing them again.
     */
    readonly resume?: boolean;
    /**
     * What started this execution, where a detached `flow.*` dispatch did —
     * which makes it a **child execution** (PRD resolved q65).
     *
     * [`runChildFlow`] passes it, and so does `src/cli.ts` for an
     * `agent-compose resume` of a child by its own id, which reads it off the
     * child's lifecycle row. It goes on that row beside the execution's inputs,
     * which is what lets a generation that resumes the child — after its parent
     * has settled, in another process — know where it came from:
     * `execution.item_index` inside it is the dispatch's (grammar 4.1), and the
     * envelope it ships is headed by it (`docs/trace.md` §2). Whoever resumes a
     * child passes it, because it is also what says the run is a child rather
     * than an invocation: its inputs are the ones its dispatch bound, never
     * parsed again (see the note at the top of the body).
     */
    readonly lineage?: runtime.Lineage;
    /**
     * Called once, **immediately before this run closes its lifecycle row**,
     * and awaited.
     *
     * The one caller is `src/serve.ts`, and what it does with it is journal the
     * `settled` webhook's intent while the row is still open
     * (`docs/durability.md` §3.7): a delivery recorded after the row closed is
     * one no restart can find — `recover` sees no open execution and the
     * delivery ledger has no row — so a process killed in that window would owe
     * a caller a push nothing would ever send. It is passed what the run
     * produced, or the error that ended it, because the report a webhook
     * carries is that answer and this is the last moment it exists inside the
     * run.
     *
     * It is **not** called for a run whose row stays open — a `human` pause
     * nobody could answer, a replay divergence — which is what keeps resolved
     * q29's "a divergence fires nothing" a property of the structure rather
     * than of a check somebody remembered to write.
     *
     * Its own failure is its own: a webhook that could not be recorded is not
     * the run's outcome, and letting it through here would replace what a run
     * really did with what a receiver's ledger could not hold.
     */
    readonly closing?: (produced: FlowRun | undefined, error: unknown) => Promise<void>;
    /**
     * Called once, **as soon as this run's lifecycle row is journaled** —
     * before the graph is streamed — and never for a run refused or failed
     * before it: an execution that is not in the journal has not begun.
     *
     * The one caller is `src/serve.ts`, for a `schedule` tick and an `event`,
     * whose admission answers that an execution started only once this is
     * called (`docs/durability.md` §3.11–§3.13). A tick's `fired` row or an
     * event's dedupe claim naming an execution the journal has no row for is
     * a claim nothing recovers, and a source checkpointed past such an event
     * hands its program a position after an event that never ran.
     */
    readonly opened?: () => void;
  } = {},
): Promise<FlowRun> {
  // **A child execution is not an invocation**, and two things below follow
  // from it (PRD resolved q65, Decision D150).
  //
  // Its inputs are the ones its dispatch bound, and they are **not parsed**
  // against the flow's `inputs:` again. What a flow's `inputs:` guards is an
  // invocation's boundary (grammar 13.2) — a trigger's payload, a command's
  // `--input` — and a dispatch is not one: grammar 8.6 rule 12 checks what a
  // `map` binds against its target's fields when the composition is built, and
  // an instance a dispatch starts runs on what it was bound, which is what a
  // joined dispatch of this same target does (`runtime.runSubflow`) and what a
  // detached one did before it had an identity of its own. Parsing here would
  // make one dispatch's validity depend on `detach:` — a `min_length:` a joined
  // item runs under would refuse the detached one — and D150 is that nothing an
  // author writes means anything else at the join.
  //
  // And **nothing it refuses goes unrecorded**. An invocation refused before its
  // row opens is answered to whoever sent it — a `400`, a usage error — and was
  // never an execution; a child has nobody to answer, so a refusal before its row
  // would be work that left no row, no lineage, no journal and no envelope, and
  // that every recovery of its parent would re-issue and lose again. So a
  // child's row opens **first**, and whatever stops it closes that row `failed`
  // and ships the envelope that says why, as every settled execution does.
  const child = options.lineage !== undefined;
  const flow: CompiledFlow | undefined = flows[address];
  const executionId = options.executionId ?? `exec_${globalThis.crypto.randomUUID()}`;
  const sessionKey = options.sessionKey ?? "";
  // Grammar 11.3, checked where the value first exists: a flow that reaches a
  // `scope: session` store keys off the identity its trigger supplies, and a run
  // started without one would silently address a partition named by the empty
  // string. `src/cli.ts` decides the same thing one step earlier for a `run`,
  // where the identity is a command-line argument; this is the guard for every
  // caller it cannot stand in for — a `serve` request, an ejected invocation —
  // where the key arrives per invocation and its absence really is a failure of
  // that run rather than of the command.
  const admitted = (): CompiledFlow => {
    if (flow === undefined) {
      throw new Error(
        `\`${address}\` is not a flow of this composition: ${Object.keys(flows).join(", ")}`,
      );
    }
    if (sessionKey === "" && flow.sessionStores.length > 0) {
      throw new Error(sessionRefusal(address, flow.sessionStores));
    }
    return flow;
  };
  const invoked = child ? undefined : admitted();
  const parsed =
    invoked === undefined ? ((inputs ?? {}) as Record<string, unknown>) : invoked.parse(inputs);
  // Before the graph is streamed, so an execution the process dies in the middle
  // of already has a row saying it was open (PRD resolved q28).
  const lineage = await runtime.openExecution({
    execution: executionId,
    flow: address,
    trigger: options.trigger ?? "manual",
    inputs: parsed,
    sessionKey,
    ...(options.callback === undefined ? {} : { callback: options.callback }),
    ...(options.traceparent === undefined ? {} : { traceparent: options.traceparent }),
    ...(options.resume === true ? { resuming: true } : {}),
    ...(options.lineage === undefined ? {} : { lineage: options.lineage }),
  });
  // The row is down: whoever was waiting for this execution to exist in the
  // journal may say it started (see the option's own comment).
  options.opened?.();
  try {
    // A child's refusals, now that it has a row to close `failed` over — see
    // the note at the top of this function.
    const compiled = invoked ?? admitted();
    const ceiling = options.recursionLimit ?? compiled.recursionLimit;
    const produced = await quiesceFlow(
      address,
      compiled,
      parsed,
      ceiling,
      { id: executionId, session_key: sessionKey, ...(lineage?.itemIndex === undefined ? {} : { item_index: lineage.itemIndex }) },
      options,
    );
    // A run that reached quiescence may still be holding a divergence raised
    // where nothing could throw it — a detached `map` delivery, which grammar 8.6
    // rule 7 says the flow instance does not wait for. PRD resolved q29 makes a
    // divergence un-absorbable by any policy at any nesting depth, and `detach:`
    // is one, so it fails the resume here rather than being reported as a
    // completion the record does not support.
    const diverged = runtime.latchedDivergence(executionId);
    if (diverged !== undefined) throw diverged;
    // The last moment before the row closes, and what `closing` is for. Its own
    // failure is swallowed rather than allowed to travel: it would report a run
    // that produced its outputs as one that failed, over a webhook the status
    // route backstops (see the option's own comment).
    if (options.closing !== undefined) {
      try {
        await options.closing(produced, undefined);
      } catch {
        // Said by the hook, where a hook has something to say.
      }
    }
    await runtime.settleExecution(executionId);
    return produced;
  } catch (error) {
    // Which of the three closing rows this is — `failed`, or none at all
    // because the run is parked at a `human` pause and is exactly what a resume
    // exists for — is `runtime.settleExecution`'s to decide, off the same
    // `runtime.interruptOf` this function's own callers read.
    //
    // …which is also what decides whether anything is *closing*: the hook is
    // the last moment before a row closes, and a row that stays open has not
    // reached one. `runtime.staysOpen` is the predicate `settleExecution` is
    // about to ask, asked here so the two cannot answer differently.
    if (options.closing !== undefined && !runtime.staysOpen(executionId, error)) {
      try {
        await options.closing(undefined, error);
      } catch {
        // …and here it would replace the error the run really produced.
      }
    }
    await runtime.settleExecution(executionId, error);
    throw error;
  } finally {
    runtime.closeExecution(executionId);
  }
}

/**
 * Run one **child execution** — what a detached `flow.*` dispatch starts (PRD
 * resolved q65) — as the ordinary execution of its flow that it is.
 *
 * The one place a child a dispatch or a recovery hands on is composed, so every
 * process that runs one runs it the same way: `runtime.dispatchChild` and
 * `runtime.resumeChild` decide *whether* a child runs, and hand it to the runner
 * the process hosts (`runtime.hostChildren`), which comes here. A child the
 * journal does not hold yet begins with its lineage on its row; one it does hold
 * replays to its frontier and reads its lineage back off that row. The one other
 * caller that resumes a child — `agent-compose resume` given the child's own id
 * — passes `runFlow` the same lineage off the same row, so a child runs on what
 * its dispatch bound whichever surface resumes it.
 *
 * No `resumable`: a child never parks, because a detached dispatch that could
 * reach a `human` node is refused at build time (Decision D118) — and were one
 * to reach one anyway, ending the run where it stands beats a wait no route
 * could ever be sent to.
 *
 * `closing` is `runFlow`'s own hook and is what a host owes a child at its
 * close: `src/serve.ts` and `src/cli.ts` journal its trace export there, on the
 * child's own ledger, exactly as they do for an execution a trigger started.
 */
export function runChildFlow(
  child: runtime.ChildExecution,
  closing?: (produced: FlowRun | undefined, error: unknown) => Promise<void>,
): Promise<FlowRun> {
  return runFlow(child.flow, child.inputs, {
    executionId: child.id,
    sessionKey: child.sessionKey,
    trigger: child.trigger,
    lineage: child.lineage,
    ...(child.resume ? { resume: true } : {}),
    ...(closing === undefined ? {} : { closing }),
  });
}

// The plain runner, hosted as this module loads: a child execution started in a
// process that owes it nothing more — an ejected caller of `runFlow` — runs and
// settles like any execution and ships nothing. `src/serve.ts` and `src/cli.ts`
// host their own over it for as long as they run (`runtime.hostChildren`).
runtime.hostChildren((child) => runChildFlow(child));

/**
 * [`runFlow`]'s body, with the journal's lifecycle row already open.
 *
 * `identity` is grammar 4.1's `execution` root for the whole run: the id and the
 * session, and — on a child execution — the source-item index of the dispatch
 * that started it, because a child execution *is* the instance a `map`
 * dispatched and `execution.item_index` is present everywhere inside one
 * (PRD resolved q65, Decision D115).
 */
async function quiesceFlow(
  address: string,
  flow: CompiledFlow,
  parsed: Record<string, unknown>,
  ceiling: number,
  identity: runtime.ExecutionIdentity,
  options: { readonly resumable?: boolean; readonly resume?: boolean },
): Promise<FlowRun> {
  const executionId = identity.id;
  // Opened before the graph is streamed, so a status route asked the instant
  // after `start` answered already has somewhere to read this run's pauses from
  // (grammar 8.7, PRD 5.11). Every instance nested inside the run registers
  // against the same execution id and is told apart by its instance path.
  runtime.openHumanWaits(executionId, options.resumable === true);
  // `scope: execution` means what it says: whatever this run's own stores held
  // is released when the run ends, however it ended (PRD 5.8, grammar 11.1).
  // A `serve` process runs many executions, so a store that stayed open would
  // be both a leak and a lifetime the composition did not declare. A pause the
  // run was holding goes the same way and for the same reason: a wait that
  // outlived its run would be one a resume could still be delivered to, with
  // no graph left to receive it (grammar 8.7).
  //
  // **Unless the run has not ended.** An execution whose journal row stays open
  // — parked at a `human` pause with nobody to answer it, or stopped by a
  // divergence — is one a resume replays, and `runtime.staysOpen` is the very
  // predicate `runtime.settleExecution` decides that by. What such a run owns
  // *on disk* has to still be there when the resumed generation reads past the
  // frontier: a replayed write is never applied a second time, so a partition
  // this generation deleted would answer an empty `get` about something the
  // execution wrote, with nothing comparing unequal to catch it
  // (`docs/durability.md` §5).
  const release = async (outcome: unknown): Promise<void> => {
    runtime.releaseHumanWaits(executionId);
    // …and the placement waits, for the same reason one level out: a dispatch
    // nothing is waiting for is work a worker could still take, whose result
    // would be posted against a node execution that is gone
    // (`docs/distributed.md` §6.1, `./mesh.ts`).
    mesh.releasePlacementWaits(executionId);
    // And the deliveries nothing joined, on the two ways out where one still in
    // flight can change what this function has to decide.
    //
    // A detached `map` delivery is journaled when it answers, so a generation
    // that walks out from under one in flight leaves an effect with no record —
    // which the generation that resumes this execution issues a second time
    // (`docs/durability.md` §3.2). That is the **parked** half, and for a run
    // that ended it costs nothing, because nothing will resume it.
    //
    // The **resuming** half is about the answer itself. A delivery is the one
    // place a `runtime.ReplayDivergence` has nothing to be thrown to, so it is
    // latched against the execution (PRD resolved q29) — and a latch is exactly
    // what makes `runtime.staysOpen` true. A delivery still working through its
    // permits when the graph quiesced can latch one *after* a reading taken
    // here, and a reading taken before that is a run closed `completed` over a
    // delivery the record describes and nobody made, or a `scope: execution`
    // blob partition removed under the very resume §5 promises it to. So a
    // generation that is consuming a record waits for them: a divergence can
    // arise on no other kind (a first generation has no record to disagree
    // with), which is why this is not a wait every run pays.
    //
    // Grammar 8.6 rule 7 is untouched either way: the join returned at
    // dispatch, the trace entry was written without it, and this is `runFlow`
    // on its way out of a run that has already stopped advancing.
    //
    // A detached `flow.*` is **not** among them: it is a child execution with
    // a record, a recovery and a divergence of its own (PRD resolved q65), so
    // neither half is about it and this run waits for it on neither. What
    // waits for a child is the process that would otherwise end under it
    // (`src/cli.ts`, `runtime.childrenSettled`).
    if (runtime.staysOpen(executionId, outcome) || options.resume === true) {
      await runtime.settleDetached(executionId);
    }
    // Read **after** the deliveries have settled, so it is the answer the whole
    // execution gives rather than the one it gave at the instant the graph
    // quiesced.
    const parked = runtime.staysOpen(executionId, outcome);
    stores.releaseExecution(executionId, parked);
    // …and the directory this run's built-in tools worked in, under the same
    // rule and for the same reason (grammar 6.1, PRD resolved q54): a workspace
    // nobody configured belongs to the execution, so it goes when the execution
    // ends — and stays where the row stays open, because the generation that
    // resumes it runs past the frontier into files the recorded prefix wrote.
    // A binding that named its own `workspace:` is the composition's and is
    // never removed.
    await runtime.releaseWorkspaces(executionId, parked);
  };
  // `runtime.quiesce` keeps the last state each superstep produced, which is
  // what makes a failure's trace survive; the one failure it restates on the way
  // out is LangGraph stopping the run at the ceiling. Its answer carries the
  // run's own failure rather than throwing it, so the release reads that error
  // on the settled path and the thrown one on the other — the same outcome
  // either way, which is what a `finally` could not have been told.
  const initial = {
    $run: {
      ...runtime.emptyRun(),
      input: parsed,
      execution: identity,
    },
  };
  let reached: { state?: GraphState; error?: unknown };
  try {
    reached = await runtime.quiesce(flow, initial, ceiling);
  } catch (thrown) {
    await release(thrown);
    throw thrown;
  }
  const { state, error } = reached;
  if (error === undefined && state === undefined) {
    // Unreachable: `streamMode: "values"` emits the state the run started from
    // before any node has run. A run with no state at all is still not one this
    // function can answer for, and saying so beats reading `undefined` as empty.
    await release(undefined);
    throw new Error(`\`${address}\` produced no state`);
  }

  // What the body answered, decided **before** the flow's `finally:` node runs:
  // a run's outputs are what its body produced, whatever its finally node then
  // does (grammar 7.9). A run that failed carries every entry that landed and
  // the aborting node's own; a run that reached quiescence and could not
  // materialize an output carries every step it took, which is the routing
  // record a reader wants most when the flow cannot say what it produced
  // (PRD 5.3).
  let trace: readonly runtime.TraceEntry[] =
    error === undefined ? (state?.$run.trace ?? []) : runtime.failedTrace(state, error);
  let ended: unknown = error;
  let what = "did not run to quiescence";
  const outputs: Record<string, unknown> = {};
  if (ended === undefined) {
    try {
      for (const field of flow.outputs) {
        outputs[field] = runtime.channelValue(
          state as unknown as Record<string, unknown>,
          field,
          `\`${address}\`'s output field \`${field}\``,
        );
      }
    } catch (cause) {
      ended = cause;
      what = "reached quiescence without an output";
    }
  }

  // The end of the run's root instance, and its `finally:` node, once: before
  // the release, because what the node works with — this run's `scope:
  // execution` stores, its workspace — is what the release lets go of (grammar
  // 7.9, PRD resolved q76). A pause the run parks at is not an end, and neither
  // is a divergence: the row stays open, and the generation that resumes it
  // runs the body on (`runtime.instanceEnding`).
  //
  // A resumed generation waits for its detached deliveries first, for the
  // release's own reason: a divergence one of them latches is what keeps the
  // row open, and it has to be read before the end is — a finally node run
  // past a record that stopped describing this run is effects the record does
  // not hold (PRD resolved q29).
  //
  // And every instance still running inside the root ends before the root's
  // own finally node runs — innermost first: a body node's failure leaves a
  // sibling branch's subflow instance where it stood, and that one is stopped
  // and its own finally node run (`runtime.endInstancesInside`).
  if (options.resume === true) await runtime.settleDetached(executionId);
  const ending = runtime.instanceEnding(executionId, ended);
  // A run somebody cancelled says so (PRD resolved q75, Decision D160).
  if (ending?.outcome === "cancelled") what = "was cancelled";
  let closing: runtime.FinallyRun | undefined;
  try {
    const inside = await runtime.endInstancesInside(
      executionId,
      "",
      address,
      ending,
      ended,
      flow.finally,
    );
    try {
      closing = await runtime.endInstance(
        flow.finally,
        (state ?? initial) as runtime.GraphStateLike,
        ending,
        trace,
      );
    } finally {
      inside();
    }
  } catch (thrown) {
    await release(thrown);
    throw thrown;
  }
  if (closing !== undefined) trace = [...trace, closing.entry];
  // A resumed run settles on the end its boundary records where its body,
  // replayed, reached another (grammar 7.9, `docs/durability.md` §3.10).
  if (ended === undefined && closing !== undefined && closing.ending.outcome !== "completed") {
    ended = new runtime.RecordedEnding(closing.ending);
    what = "ended as its journal records";
  }
  await release(ended);
  const finallyError = runtime.finallyErrorOf(executionId);
  if (ended !== undefined) {
    throw new runtime.FlowFailure(address, what, trace, ended, finallyError);
  }
  return {
    outputs,
    trace,
    state: (closing?.state ?? state) as GraphState,
    ...(finallyError === undefined ? {} : { finallyError }),
  };
}

/**
 * A new builder over this composition's state model.
 *
 * Every flow's topology is added to one of these. Constructing it is also what
 * proves the state model is a shape LangGraph accepts — a channel spec it
 * refuses fails here rather than at the first invocation.
 */
export function createBuilder() {
  return new StateGraph(State);
}

/**
 * What each placed call site does, for the process that **executes** it
 * (`docs/distributed.md` §3.2, §7.4).
 *
 * The other side of `mesh.dispatchPlaced`. A hub journals a dispatch and waits;
 * the worker that takes it runs `./worker-node.ts`, which looks the dispatch's
 * `node` up here and runs exactly the activity this node would have run had
 * nothing been placed. One lowering, two processes — which is what keeps a
 * placed node from meaning something different from an unplaced one.
 *
 * Keyed by the address a dispatch names: `<flow>.<node>` for an `agent:` or
 * `function:` node, and the component's own address for a `map` dispatch target
 * (grammar §14.1's three ways a graph reaches a placed component).
 */
export const placedNodes: Readonly<Record<string, mesh.PlacedRun>> = {};

/**
 * Every `human:` node this composition declares, by `<flow address>.<node id>`.
 *
 * Read by the hub alone, and for one thing: a pause a **worker** opened settles
 * its dispatch paused (`docs/distributed.md` §3.4), and the hub plants the wait
 * on its own board under the identity the worker derived. What an answer is held
 * to, and what a status route publishes as the contract, are then this node's own
 * — the artifact is everywhere (§4.3), so the descriptor never travels.
 */
runtime.registerHumanNodes({
  "flow.shape.ask": flowShapeNodeAskHuman,
});
